function splitStorySentences(text:string){const normalized=text.replace(/\n+/g," ").replace(/\s+/g," ").trim();return normalized.match(/[^۔.!؟?]+[۔.!؟?]?/g)?.map(part=>part.trim()).filter(Boolean)??(normalized?[normalized]:[])}
function includesTerm(text:string,terms:string[]){const lower=text.toLowerCase();return terms.some(term=>lower.includes(term.toLowerCase()))}
function hasProphetFigure(title:string,text:string){return includesTerm(`${title} ${text}`,prophetTerms)}
function classifyVisualScene(text:string,language:"ur"|"en"){const rule=visualRules.find(item=>includesTerm(text,item.terms));return rule?{kind:rule.kind,label:language==="ur"?rule.ur:rule.en}:{kind:"general" as VisualKind,label:language==="ur"?"واقعہ آگے بڑھتا ہے":"Story moment"}}
function buildVisualScenes(title:string,body:string,language:"ur"|"en"){const parts=splitStorySentences(body),groupSize=Math.max(1,Math.ceil(parts.length/28)),groups:string[]=[];for(let index=0;index<parts.length;index+=groupSize)groups.push(parts.slice(index,index+groupSize).join(" "));return (groups.length?groups:[body||title]).map(caption=>{const visual=classifyVisualScene(caption,language);return{...visual,caption,prophetPresent:hasProphetFigure(title,caption)}})}
function sceneAtRatio(scenes:VisualScene[],ratio:number){const clamped=Math.max(0,Math.min(.9999,ratio)),weights=scenes.map(scene=>Math.max(70,scene.caption.length)),total=weights.reduce((sum,item)=>sum+item,0);let cursor=0;for(let index=0;index<scenes.length;index+=1){const start=cursor/total;cursor+=weights[index];const end=cursor/total;if(clamped<end)return{scene:scenes[index],index,sceneRatio:(clamped-start)/Math.max(.0001,end-start)}}return{scene:scenes[scenes.length-1],index:scenes.length-1,sceneRatio:1}}

type SavedVideo={blob:Blob;language:"ur"|"en"};
function openVideoStore(){return new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open("noor-studio",1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains("videos"))request.result.createObjectStore("videos")};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveStoryVideo(storyId:number,video:SavedVideo){const db=await openVideoStore();await new Promise<void>((resolve,reject)=>{const transaction=db.transaction("videos","readwrite");transaction.objectStore("videos").put(video,String(storyId));transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error)});db.close()}
async function loadStoryVideo(storyId:number){const db=await openVideoStore();const video=await new Promise<SavedVideo|undefined>((resolve,reject)=>{const request=db.transaction("videos","readonly").objectStore("videos").get(String(storyId));request.onsuccess=()=>resolve(request.result as SavedVideo|undefined);request.onerror=()=>reject(request.error)});db.close();return video}

